// Zweck: HTTP-POST für relay_1 in einen MQTT-Befehl umwandeln.
// Eingabe:  msg.payload – JSON-Body mit device_id und relay_1 (true/false)
// Ausgaben:
//   Output 1 – MQTT-Nachricht für den Broker (topic + payload aus commandMinimal)
//   Output 2 – HTTP-Antwort an den Aufrufer (202 Accepted oder Fehler)
//
// Fehlerverhalten:
//   - Helper fehlt         → 500 Internal Server Error
//   - Validierungsfehler  → 400 Bad Request mit error/message
//   - Unerwarteter Fehler → 500 mit error.message

const commandMinimal = global.get("commandMinimal");

// Sicherheitscheck: commandMinimal muss als globaler Helper vorhanden sein.
if (!commandMinimal || typeof commandMinimal.buildNetErlRelay1Command !== "function") {
    msg.statusCode = 500;
    msg.payload    = { error: "command_minimal_unavailable", message: "command helper missing" };
    return [null, msg];
}

try {
    const runtime = global.get("smarthome_runtime");
    const result  = commandMinimal.buildNetErlRelay1Command(runtime, msg.payload);

    // Fachlogik hat den Befehl abgelehnt (z. B. Gerät offline, unbekannte device_id).
    if (!result.ok) {
        msg.statusCode = result.statusCode || 400;
        msg.payload    = { error: result.error, message: result.message };
        return [null, msg];
    }

    // Erfolg: MQTT-Nachricht und HTTP-Antwort parallel zurückgeben.
    const mqttMsg = {
        topic:   result.command.topic,
        payload: JSON.stringify(result.command.payload),
        qos:     0,
        retain:  false
    };
    const responseMsg = {
        req:        msg.req,
        res:        msg.res,
        statusCode: 202,
        payload:    result.response
    };
    return [mqttMsg, responseMsg];

} catch (error) {
    // Unerwarteter Laufzeitfehler – vollständig loggen.
    node.error(error, msg);
    msg.statusCode = 500;
    msg.payload    = { error: "command_minimal_internal", message: error.message };
    return [null, msg];
}

// Zweck: HTTP-POST für Rolladen-Befehle (open/close/stop/set_position) in MQTT umwandeln.
// Eingabe:  msg.payload – JSON-Body mit device_id, command, ggf. position
// Ausgaben:
//   Output 1 – MQTT-Nachricht für den Broker
//   Output 2 – HTTP-Antwort an den Aufrufer (202 Accepted oder Fehler)
//
// Gleiche Fehlerbehandlungsstruktur wie Relay-1-Endpunkt (400/500 mit JSON-Body).

const commandMinimal = global.get("commandMinimal");

if (!commandMinimal || typeof commandMinimal.buildCoverCommand !== "function") {
    msg.statusCode = 500;
    msg.payload    = { error: "command_minimal_unavailable", message: "command helper missing" };
